function validate([word, k]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 500000) return 'word needs 1 to 500,000 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 2000) return 'k is a whole number from 1 to 2000.';
  return null;
}

