function possibleStringCount(word, k) {
  const MOD = 1e9 + 7;
  const groups = [];
  let run = 1;
  for (let i = 1; i <= word.length; i++) {
    if (i < word.length && word[i] === word[i - 1]) {
      run++;
    } else {
      groups.push(run);
      run = 1;
    }
  }

  let total = 1;
  for (const size of groups) {
    total = (total * size) % MOD;
  }
  const budget = k - 1 - groups.length;
  if (budget < 0) {
    return total;
  }

  const dp = new Array(budget + 1).fill(0);
  dp[0] = 1;
  const prefix = new Array(budget + 2).fill(0);
  for (const size of groups) {
    for (let s = 0; s <= budget; s++) {
      prefix[s + 1] = (prefix[s] + dp[s]) % MOD;
    }
    for (let s = 0; s <= budget; s++) {
      const low = Math.max(0, s - size + 1);
      dp[s] = (prefix[s + 1] - prefix[low] + MOD) % MOD;
    }
  }

  let tooShort = 0;
  for (const ways of dp) {
    tooShort = (tooShort + ways) % MOD;
  }
  return (total - tooShort + MOD) % MOD;
}

