function possibleStringCount(word, k) {
  // Exact BigInt counts of the originals of every length: each run of equal letters keeps 1..run of its letters.
  const runs = word.match(/(.)\1*/g).map(r => r.length);
  let byLength = [1n];
  for (const run of runs) {
    const next = new Array(byLength.length + run).fill(0n);
    byLength.forEach((ways, len) => { for (let keep = 1; keep <= run; keep++) next[len + keep] += ways; });
    byLength = next;
  }
  let count = 0n;
  byLength.forEach((ways, len) => { if (len >= k) count += ways; });
  return Number(count % 1000000007n);
}

