function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    const n = 1 + pick(12);
    const alphabet = 1 + pick(3);
    let word = '';
    for (let i = 0; i < n; i++) word += letters[pick(alphabet)];
    const k = rand() < 0.1 ? 1 + pick(2000) : 1 + pick(n + 2);
    return [word, k];
  }
  // Large: about 10,000 letters split into runs; usually fewer runs than k, so the knapsack has real work.
  const k = 1500 + pick(501);
  const runCount = rand() < 0.25 ? k + pick(500) : 400 + pick(k - 400);
  const length = 9000 + pick(1001);
  const runs = new Array(runCount).fill(1);
  for (let extra = length - runCount; extra > 0; extra--) runs[pick(runCount)]++;
  let word = '', prev = -1;
  for (const run of runs) {
    const letter = prev < 0 ? pick(26) : (prev + 1 + pick(25)) % 26;
    word += letters[letter].repeat(run);
    prev = letter;
  }
  return [word, k];
}
